import{_ as e,c as a,o,ae as r}from"./chunks/framework.Bi6zybwU.js";const g=JSON.parse('{"title":"Import Table from TablePress Plugin","description":"Import Table from TablePress Plugin","frontmatter":{"title":"Import Table from TablePress Plugin","description":"Import Table from TablePress Plugin"},"headers":[],"relativePath":"guide/import-export/import-table-from-tablepress-plugin.md","filePath":"guide/import-export/import-table-from-tablepress-plugin.md"}'),l={name:"guide/import-export/import-table-from-tablepress-plugin.md"};function s(i,t,n,p,b,m){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="import-table-from-tablepress-plugin" tabindex="-1">Import Table from TablePress Plugin <a class="header-anchor" href="#import-table-from-tablepress-plugin" aria-label="Permalink to &quot;Import Table from TablePress Plugin&quot;">​</a></h1><p>You can import tables from other WordPress plugins, besides importing tables from **CSV/JSON **files. And Ninja Tables can display data from TablePress if you import. Find the &quot;<strong>Import From Other WP Table</strong> <strong>Plugin</strong>&quot; section under the **Import Table **option.</p><h2 id="import-tablepress-data-into-ninja-tables" tabindex="-1">Import TablePress Data into Ninja Tables <a class="header-anchor" href="#import-tablepress-data-into-ninja-tables" aria-label="Permalink to &quot;Import TablePress Data into Ninja Tables&quot;">​</a></h2><p>To import a table from the TablePress Plugin, you need the <strong><a href="https://tablepress.org/" target="_blank" rel="noreferrer">TablePress</a></strong> plugin pre-installed and a table ready to import. Let&#39;s have a look at the article on how to accomplish that.</p><ul><li><p>First, create a table in TablePress and name it.</p></li><li><p>Have a look at the screenshot below, which is a table made using <strong>TablePress</strong>. <img src="https://ninjatables.com/wp-content/uploads/2022/09/01-2-scaled.webp" alt="Table made of TablePress"></p></li><li><p>Now, go to the WordPress <strong>Dashboard → Ninja Tables → Tools → Import</strong> to import this table from the TablePress Plugin.</p></li><li><p>Scroll down, and you will get the &quot;<strong>Import From Other WP Table Plugin</strong>&quot; option. <img src="https://ninjatables.com/wp-content/uploads/2022/09/02-2-scaled.webp" alt=""></p></li><li><p>Click on the <strong>Import</strong> button to import from TablePress.</p></li><li><p>A popup will appear after that. Click on the Import button (right side of the table) &amp; a button will appear beside the Import button, the <strong>View</strong> <strong>Imported</strong> <strong>Table</strong> button.</p></li><li><p>By clicking on that button, you can view the imported table. <img src="https://ninjatables.com/wp-content/uploads/2022/09/03-2.webp" alt="View Imported Table"></p></li><li><p>From the list of available Tables in TablePress, choose the table that you want to import into Ninja Tables.</p></li></ul>',5)])])}const d=e(l,[["render",s]]);export{g as __pageData,d as default};
